import sys

def main():
    s = sys.stdin.readline().strip()
    if not s:
        return

    upper_count = sum(1 for c in s if c.isupper())
    lower_count = len(s) - upper_count

    if upper_count > lower_count:
        print(s.upper())
    else:
        print(s.lower())

if __name__ == "__main__":
    main()
